"""roster remarks, event lines, piano/fart reactions, laughs (222 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'remark', 'text': 'En seize, il y avait moins de boue que dans ce jardin.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un bon cheval vaut mieux que dix invités.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce jazz me donne des crampes au mollet.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'De mon temps, les bals finissaient à vingt-deux heures. Par une charge.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Cette tempête me rappelle la Somme. En plus sec.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai connu des tranchées plus gaies que ce salon.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le cognac d'Ashcombe est buvable. Pour un Anglais.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mes médailles pèsent plus lourd que mon assiette.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "On m'a confisqué mon sabre à l'entrée. Scandaleux.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Cette moustache m'a coûté vingt ans de cire.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je n'ai jamais reculé. Sauf devant ma belle-mère.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un régiment de serveurs, et pas un pour le cognac.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mon genou annonce de la pluie. Il a raison, comme toujours.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ces jeunes gens ne savent plus marcher au pas.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Qui a mis du jazz sur le gramophone ? Qu'on le fusille !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Il me faudrait une carte d'état-major pour trouver les toilettes.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ashcombe m'a promis une chasse au renard demain. Avec ce temps, ce sera au canard.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ces messieurs en imperméable saluent mal. Des civils, sans aucun doute.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai perdu mon épouse. Dans la salle de bal, j'entends. Pas à la guerre.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Bon. Où est passé ce maudit cognac ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Ça brûle dans l'aile ouest, ne passez pas par là !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Des seaux, des seaux, bon sang de bonsoir !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Allumez une bougie, sacrebleu, on n'y voit rien !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_colonel_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Personne ne touche à mes médailles dans le noir !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_colonel_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ! Si j'avais mon sabre...", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Restez groupés ! On ne tire pas sur un carré !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Ce fou va tout faire sauter ! Écartez-vous de lui !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un automate en armure ? Même les Prussiens n'ont pas osé !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est maîtrisé. Pas grâce aux civils.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_colonel_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière ! Inspection des poches, messieurs dames.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_colonel_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Qui massacre ce piano ? Au poteau !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'On dirait la charge de Reichshoffen.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Silence dans les rangs, au piano !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Qui a lâché ça ? Un gaz de combat, ma parole !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ! Ha ! Ha !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_colonel_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ho ho ho !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_colonel_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hrm, hm hm !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_colonel_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Les Carpates me manquent. On y entendait les loups.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce manoir manque de cercueils. Pardon, de caractère.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je ne bois jamais... de vin.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mes ancêtres donnaient aussi des bals. Les invités restaient très longtemps.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le soleil se lève à quelle heure, déjà ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce miroir doit être cassé. Je n'y vois que la salle.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Quelle belle collection de cous, ce soir.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La cuisine sent l'ail. C'est une provocation.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Dans mon château, le majordome a deux cents ans. Il commence à fatiguer.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'adore les nuits de tempête. Personne ne peut repartir.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le sang bleu est surfait. Je préfère le rouge.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Une chauve-souris dans le hall ? Ce n'est qu'un cousin.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je ne vieillis pas. Je me bonifie.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le dernier bateau est parti. Quel dommage. Pour eux.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Trop de bougies. On y voit comme en plein jour.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ashcombe sert un bordeaux correct. Un peu pâle.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je dors très bien, merci. Toute la journée.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Mon tailleur de Bucarest est mort en seize cent vingt. Je ne l'ai jamais remplacé.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le crucifix du couloir est d'un goût douteux.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Minuit approche. Enfin, la soirée commence.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Le feu ! Ne m'approchez pas de ces flammes !", 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Éteignez-moi ça, l'odeur de brûlé m'est insupportable !", 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Ah, la nuit tombe enfin sur ce manoir.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_comte_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "N'ayez crainte. Dans le noir, je suis chez moi.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_comte_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des brigands ! Chez nous, on les empalait.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Gardez vos bijoux, ces rustres n'ont aucun goût.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Cet homme hurle comme un loup blessé. Éloignez-vous de lui.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Une créature de fer ? Au moins, elle n'a pas de sang.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Je respire à nouveau. Façon de parler.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_comte_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "Déjà la lumière ? C'était si reposant.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_comte_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ce piano agonise. J'aime ça.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Liszt jouait mieux. Je l'ai entendu.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Un nocturne ? Non. Un massacre.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Quelle odeur... Même mon caveau sent meilleur.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Mwa ha ha...', 'voice': 'char_comte', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_comte_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha...', 'voice': 'char_comte', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_comte_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hé hé hé...', 'voice': 'char_comte', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_comte_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Trois fiançailles, et pas un seul mariage. Je suis une artiste.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Cette émeraude ? Un cadeau. Je ne sais plus de qui.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le champagne est tiède. Comme la conversation.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je connais le secret de chacun ici. Sauf le mien, je l'ai oublié.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Lady Ashcombe porte du faux. Je le sais, j'ai le vrai.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Avec cette tempête, personne ne pourra s'enfuir. Délicieux.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel m'a raconté Verdun pour la quatrième fois.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Un homme masqué m'a fait un baisemain. J'espère que c'était Victor.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je déteste les soirées où je ne suis pas la plus regardée.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le comte ne mange rien. Il me regarde manger. C'est troublant.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ma mère disait : épouse un homme riche. Elle n'a pas dit lequel.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce masque doré me va bien, non ? Évidemment qu'il me va bien.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je parie que le testament d'Ashcombe fera des malheureux.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "On a volé le collier de quelqu'un. Pas le mien. Quel affront.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Il pleut tellement que mes boucles se défrisent.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Qui est ce monsieur en bleu nuit ? Trop mystérieux pour être honnête.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je collectionne les cœurs brisés. C'est moins encombrant que les bijoux.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Si je m'ennuie encore une heure, je provoque un scandale.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Odette chante comme un ange. Un ange de Pigalle, mais un ange.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce soir, j'ai décidé d'être sage. Jusqu'à minuit.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu se propage ! Sauvez les fourrures !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'La fumée ! Mes poumons, ma robe, tout !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Qui a éteint ? Si c'est une blague, elle est ratée.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_f_gown_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, tout le monde va me voler mes bijoux.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_f_gown_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des bandits ! Cachez vos bijoux, ils visent les perles !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Ne me regardez pas, je n'ai rien de valeur. Presque rien.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Cet homme hurle qu'il va tout faire sauter ! Faites-le taire !", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Un robot ? Mais qui a invité une machine ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Mes cheveux sentent le roussi.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_f_gown_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "Enfin la lumière. J'ai encore toutes mes bagues ? Oui.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_f_gown_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Quelle horreur. On dirait mon troisième fiancé au piano.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Qui joue ? Qu'on lui confisque ses mains.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ce n'est plus de la musique, c'est un aveu.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Oh ! Qui a fait ça ? C'est d'un vulgaire...", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_f_gown_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hi hi hi...', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_f_gown_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ah ha ha !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_f_gown_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "J'ai perdu ma montre au baccara. Et le baccara aussi.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Cette queue-de-pie m'a coûté trois mois de loyer. Pas encore payés.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je ne suis pas ruiné. Je suis momentanément élégant.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Il me faut une héritière avant minuit.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La roulette m'aime. Elle a juste une drôle de façon de le montrer.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le champagne est gratuit. C'est la seule raison de ma présence.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ma tante m'a déshérité. Deux fois. Elle a de la suite dans les idées.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ne faites jamais confiance à un homme en queue-de-pie. Sauf à moi.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai un système infaillible pour la roulette. Il a échoué onze fois.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce soir, je suis riche. Demain, on verra.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Si on me cherche, je suis à la bibliothèque. Personne ne cherche dans une bibliothèque.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Une valse, une coupe, une héritière. Le programme est simple.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce manoir vaut une fortune. Je me demande si Ashcombe a une fille.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai les poches vides et le cœur plein. Surtout les poches.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mes chaussures vernies brillent plus que mon avenir.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je ne mens jamais. J'arrange la vérité.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La tempête m'arrange. Mes créanciers ne savent pas nager.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Sandra m'a encore dit non. Elle dit toujours non avant de dire oui.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Qui veut jouer ? Petites mises, gros sourires.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un gentleman ne compte jamais. Surtout pas ses dettes.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu gagne la salle de jeu ! Mes jetons !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Sortons, la fumée abîme les revers de soie !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, tout le monde est beau. Même le colonel.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_m_tailcoat_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Rallumez, je n'arrive pas à tricher dans le noir !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_m_tailcoat_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ! J'espère qu'ils ne viennent pas récupérer leur argent.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Tenez, prenez mon portefeuille. Il est vide, mais il est en cuir.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Ce type crie qu'il va tout faire sauter ! Je ne parie pas contre lui.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un robot ! Il doit valoir une fortune. S'il voulait bien arrêter de tirer.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Mon élégance aussi, un peu.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_m_tailcoat_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'Ah, la lumière ! Tout le monde a encore ses bijoux ? Dommage.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_m_tailcoat_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Bravo ! Enfin quelqu'un qui joue plus mal que moi.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Qui a payé ce pianiste ? Qu'on le rembourse.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ce piano a perdu plus que moi au baccara.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Ah ! Ce n'est pas moi. J'ai bien trop de classe pour ça.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_m_tailcoat_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_m_tailcoat_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hé hé !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_m_tailcoat_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'La nuit ne ment jamais. Les gens, si.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Quelqu'un ici a quelque chose sur la conscience.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le majordome a regardé l'horloge trois fois. Il attend quelque chose.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je veille.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Trente-neuf invités. Et un de trop.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le crime adore les bals masqués.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Minuit approche. C'est mon heure.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Les hommes en imperméable ne voient que ce qu'on leur montre.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai compté les couteaux à poisson. Il en manque un.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La pluie efface les traces. Pratique, pour certains.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Un masque ne cache rien. Il révèle ce qu'on voudrait être.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Quelqu'un a coupé la ligne du téléphone. Ce n'était pas la tempête.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Personne ne remarque celui qui reste immobile.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai déjà vu ce visage. Sur une affiche.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La justice attend. Moi aussi.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Méfiez-vous d'un homme qui rit trop fort.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le coffre du bureau a été ouvert. Puis refermé. Avec soin.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les éclairs montrent tout. Pendant une seconde.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je ne suis pas un héros. Je suis ponctuel.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Deux portes, un escalier, une fenêtre. Toujours repérer les sorties.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Ce feu a été allumé. Je sens l'essence.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Évacuez l'aile est ! Le feu remonte le couloir !", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'La nuit est tombée sur le manoir. Restez près des murs.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_minuit_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Dans l'obscurité, c'est moi qui veille.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_minuit_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des bandits. Ils savaient exactement par où entrer.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Ne jouez pas les héros. C'est mon travail.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Cet homme porte de la dynamite. Éloignez-vous, vite.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Une machine. Quelqu'un ici la commande.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est mort. Les indices aussi, sans doute.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_minuit_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière revient. Regardez qui n'est plus à sa place.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_minuit_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ce vacarme est une diversion.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Quelqu'un joue pour couvrir un autre bruit.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Hm. Même la nuit a ses limites.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Hm. Un crime. Un vrai.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hm hm.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_minuit_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Heh.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_minuit_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hm hm hm...', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_minuit_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Dans mon quartier, on appellerait ça une fête de croque-morts.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ils mangent le caviar comme nous on mange des frites.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai chanté devant des marins, je peux bien chanter devant des comtes.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mes perles sont fausses, mais mon sourire est vrai.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le champagne, c'est bien joli, mais un petit blanc au comptoir...", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Si ma mère me voyait ici, elle ferait le signe de croix.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les riches applaudissent avec deux doigts. Ça fait pas de bruit.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Il pleut des cordes. Comme à Montmartre, mais sans les pavés.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel me fait de l'œil. Il en a qu'un qui marche.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce piano est désaccordé. Comme la moitié des invités.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai les pieds en compote. Ces chaussures, c'est de la torture.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Si on me paie, je chante jusqu'à l'aube. Sinon, jusqu'à minuit.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le comte me regarde le cou. J'ai une tache ou quoi ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Faut que je trouve le pianiste. On répète à minuit.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ces plumes me chatouillent le nez depuis le dîner.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les rupins parlent fort, mais ils disent rien.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_16', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ah, l'odeur du cigare. Ça me rappelle les loges.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je suis montée sur scène à quinze ans. Sur une table, mais une scène quand même.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_18', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Victor m'a encore demandé de l'argent. Le pauvre, il me croit riche.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_19', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Bon. Qui c'est qui m'offre à boire ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_20', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Ça brûle dans la salle de bal ! Mes partitions !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'La fumée ! On voit plus rien, sortez !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Hé, le noir ! C'est l'entracte, ou quoi ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_odette_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Tenez-vous la main, on va s'en sortir.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_odette_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des malfrats ! Je connais ce genre-là, ils rigolent pas.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Planquez vos bijoux, les gars sont là pour ça.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_attack_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Il a de la dynamite plein les poches, ce dingue !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Un robot ! On se croirait au cinéma, en pire.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': "C'est éteint ? Ouf. J'ai cru que j'allais finir en grillade.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_odette_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière ! Tout le monde est là ? Bon.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_odette_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Oh là là, qui c'est qui massacre mon piano ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ça, c'est pas du jazz, c'est un accident.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Pousse-toi, je vais te montrer comment on joue !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Oh, la vache ! Qui a fait ça ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_odette_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hi hi hi !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_odette_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Oh ha ha ha !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_odette_laugh_03', 'whispered': False, 'nonverbal': True, 'gun': False},
]
